import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Daftar d = new Daftar();
        d.email = "sari";
        for (Field f : Daftar.class.getDeclaredFields()) {
            Pola p = f.getAnnotation(Pola.class);
            String nilai = (String) f.get(d);
            if (p != null && !nilai.matches(p.value())) {
                System.out.println(f.getName() + " tidak cocok dengan " + p.value());
            }
        }
    }
}

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@interface Pola {
    String value();
}

class Daftar {
    @Pola(".+@.+")
    String email;

    @Pola("[0-9]+")
    String hp = "0812";
}

