import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class Main {
    static List<String> periksa(Object o) throws IllegalAccessException {
        List<String> salah = new ArrayList<>();
        for (Field f : o.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Object nilai = f.get(o);
            if (f.isAnnotationPresent(Wajib.class) && (nilai == null || nilai.toString().trim().isEmpty())) {
                salah.add(f.getName() + ": wajib diisi");
            }
            Panjang p = f.getAnnotation(Panjang.class);
            if (p != null && nilai != null && nilai.toString().length() > p.maks()) {
                salah.add(f.getName() + ": maksimal " + p.maks() + " huruf");
            }
        }
        return salah;
    }

    public static void main(String[] args) throws Exception {
        System.out.println(periksa(new FormTodo("Belajar", "Sari")));
        System.out.println(periksa(new FormTodo("", null)));
    }
}

